// saturated is a weight set whose tag sums tower past TagCap — the
// "affinity can never buy a context tier" fixture.
var saturated = Weights{"action": 500, "thriller": 500, "drama": 500}

func TestScoreTierDominance(t *testing.T) {
	tests := []struct {
		name string
		e    EntityState
		w    Weights
		want float64
	}{
		{name: "in progress alone", e: EntityState{InProgress: true}, w: nil, want: 1000},
		{name: "new episode alone", e: EntityState{NewEpisode: true}, w: nil, want: 500},
		{
			name: "max affinity alone never reaches a context tier",
			e:    EntityState{Tags: []string{"action", "thriller", "drama"}},
			w:    saturated,
			want: 400,
		},
		{
			name: "in progress outranks new episode plus capped tags",
			e:    EntityState{InProgress: true, Tags: []string{"action", "thriller", "drama"}},
			w:    saturated,
			want: 1000 + 400,
		},
		{
			name: "completed entity loses the resume bonus",
			e:    EntityState{InProgress: false, Tags: []string{"action"}},
			w:    nil,
			want: 1,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := Score(tt.e, tt.w); got != tt.want {
				t.Fatalf("Score(%+v) = %v, want %v", tt.e, got, tt.want)
			}
		})
	}
	// The pinned chain, asserted on the table's own values: resume >
	// resume + any affinity; new episode > max affinity.
	if BonusInProgress <= BonusNewEpisode+TagCap {
		t.Errorf("tier law broken: BonusInProgress %v must exceed BonusNewEpisode+TagCap %v",
			BonusInProgress, BonusNewEpisode+TagCap)
	}
	if BonusNewEpisode <= TagCap {
		t.Errorf("tier law broken: BonusNewEpisode %v must exceed TagCap %v", BonusNewEpisode, TagCap)
	}
}

