func TestZeroInterestFloor(t *testing.T) {
	tests := []struct {
		name string
		e    EntityState
		w    Weights
		want float64
	}{
		{
			name: "no tags, no interest scores zero",
			e:    EntityState{},
			w:    nil,
			want: 0,
		},
		{
			name: "every tag is its base weight of one",
			e:    EntityState{Tags: []string{"action", "thriller", "drama"}},
			w:    nil,
			want: 3,
		},
		{
			name: "explicit zero interest equals the missing-key base",
			e:    EntityState{Tags: []string{"action", "thriller"}},
			w:    Weights{"action": 0, "thriller": 0},
			want: 2,
		},
		{
			name: "case variant tags still score one base each",
			e:    EntityState{Tags: []string{" Action ", "ACTION"}},
			w:    Weights{"action": 0},
			want: 2,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := Score(tt.e, tt.w); got != tt.want {
				t.Fatalf("Score(%+v) = %v, want %v", tt.e, got, tt.want)
			}
		})
	}
	// Zero interest degrades to the alphabetical floor: with every entity
	// carrying an equal tag count, Order falls to display name ascending.
	grid := []Entry{
		{ID: "1", DisplayName: "Бета", Score: Score(EntityState{Tags: []string{"a"}}, nil)},
		{ID: "2", DisplayName: "Альфа", Score: Score(EntityState{Tags: []string{"b"}}, nil)},
	}
	Order(grid)
	if grid[0].DisplayName != "Альфа" || !reflect.DeepEqual(
		[]float64{grid[0].Score, grid[1].Score}, []float64{1, 1}) {
		t.Fatalf("zero-interest grid not alphabetical at equal tag counts: %+v", grid)
	}
	if math.Abs(grid[1].Score-1) > 1e-9 {
		t.Errorf("base tag weight drifted: %v, want 1", grid[1].Score)
	}
}
